import kotlinx.coroutines.*

fun main() = runBlocking {
    val handler = CoroutineExceptionHandler { _, e -> println("handler: ${e.message}") }
    val scope = CoroutineScope(SupervisorJob() + handler)
    val d = scope.async { error("async failed") }
    val j = scope.launch { error("launch failed") }
    j.join()
    try {
        d.await()
    } catch (e: IllegalStateException) {
        println("await: ${e.message}")
    }
}

scope.launch(SupervisorJob()) {
    launch { error("first failed") }
    launch { delay(100); println("second done") }
}
